package server

import "github.com/Autumn-27/artex/config"

// Catalog that translates user-facing backend messages (Korean originals) into the active
// output language. In this repository, writeErr response text · some writeJSON error fields
// are written as Korean constants · literals (F3b/F34). Here those Korean originals are the
// keys and the English · Chinese · Spanish translations are the values. Korean (ko) is the
// key itself and is not stored; on a lookup miss or when the language is ko, the original is
// returned as-is.
//
// Keys are generated by extracting the Korean constants/literals byte for byte from the
// source (with help from scripts). Since they are not typed by hand, keys never drift from
// the runtime values passed to writeErr and silently go missing.
//
// For format string constants (%d · %s · %w, etc.) the formatted result differs from the key,
// so the call site first translates the template itself via trMsg(template) before passing
// it to fmt.Sprintf/fmt.Errorf.

// trMsg translates a Korean original message into the active output language. If it is not
// in the catalog or the active language is Korean, the original is returned as-is.
// config.ActiveLanguage reflects the runtime setting (settings table), so the language the
// user picked takes effect immediately.
func trMsg(ko string) string {
	if m, ok := errCatalog[ko]; ok {
		if v, ok2 := m[config.ActiveLanguage()]; ok2 && v != "" {
			return v
		}
	}
	return ko
}

// loadOutputLanguage resolves the user-facing output language from the source of
// truth: the runtime setting (settings table) over config.Language() (ARTEX_LANG >
// config file > ko). Call it only to (re)fill the cache; it does a DB query and a
// config file read.
func (s *Server) loadOutputLanguage() string {
	if s.m != nil && s.m.pg != nil {
		if v, ok, _ := s.m.pg.GetSetting(settingOutputLanguage); ok {
			if nv := config.NormalizeLanguage(v); nv != "" {
				return nv
			}
		}
	}
	return config.Language()
}

// outputLanguage returns the cached output language, resolving it on first use.
func (s *Server) outputLanguage() string {
	if v, ok := s.outputLang.Load().(string); ok && v != "" {
		return v
	}
	v := s.loadOutputLanguage()
	s.outputLang.Store(v)
	return v
}
